package notify;

import static readcode.Assert.*;

import java.util.Map;

import notify.config.AppConfig;
import notify.mail.Mailer;
import notify.service.ShipmentNotifier;

public class NotifierTest {

    private Mailer.Recording mailer;

    public void setUp() {
        mailer = new Mailer.Recording();
    }

    private ShipmentNotifier notifierFor(String appEnv) {
        // values read from the real process environment are never interned literals
        Map<String, String> env = Map.of("APP_ENV", new String(appEnv));
        return new ShipmentNotifier(AppConfig.fromEnv(env), mailer);
    }

    public void testConfigDefaultsToDevelopment() {
        assertEquals("development", AppConfig.fromEnv(Map.of()).environment());
    }

    public void testConfigNormalisesEnvironmentName() {
        assertEquals("production", AppConfig.fromEnv(Map.of("APP_ENV", "  Production ")).environment());
    }

    public void testProductionSendsToTheCustomer() {
        notifierFor("production").shipped("ana@customer.test", "A-100", "UPS");
        Mailer.Message sent = mailer.sent().get(0);
        System.out.println("to=" + sent.to() + " subject=" + sent.subject());
        assertEquals("ana@customer.test", sent.to(), "production mail must reach the customer");
    }

    public void testProductionSubjectHasNoEnvironmentPrefix() {
        notifierFor("PRODUCTION").delayed("ana@customer.test", "A-101", 2);
        assertEquals("Order A-101 is delayed", mailer.sent().get(0).subject());
        assertEquals("ana@customer.test", mailer.sent().get(0).to());
    }

    public void testStagingRedirectsToSandbox() {
        notifierFor("staging").shipped("ana@customer.test", "A-102", "DHL");
        Mailer.Message sent = mailer.sent().get(0);
        assertEquals("mail-sink@example.test", sent.to());
        assertTrue(sent.subject().startsWith("[staging] "), sent.subject());
    }

    public void testDevelopmentRedirectsToConfiguredSandbox() {
        AppConfig config = AppConfig.fromEnv(Map.of("MAIL_SANDBOX_RECIPIENT", "qa@example.test"));
        new ShipmentNotifier(config, mailer).delayed("ana@customer.test", "A-103", 1);
        assertEquals("qa@example.test", mailer.sent().get(0).to());
    }

    public void testProductionRefundGoesToTheCustomer() {
        notifierFor("production").refunded("ana@customer.test", "A-105", 1999);
        Mailer.Message sent = mailer.sent().get(0);
        assertEquals("ana@customer.test", sent.to());
        assertTrue(sent.body().contains("19.99"), sent.body());
    }

    public void testSandboxMailKeepsOriginalRecipientInBody() {
        notifierFor("staging").shipped("ana@customer.test", "A-104", "FedEx");
        assertTrue(mailer.sent().get(0).body().contains("ana@customer.test"), "body should name the real customer");
    }
}
